  "cypher": "MATCH (c:Company)
WHERE EXISTS {
  MATCH (c)-[:hasCEO]->(p:Person)
  WHERE p.name = 'Bob Swan'
} OR EXISTS {
  MATCH (c)-[:operatesIn]->(i:Industry)
  WHERE i.name = 'electrical industry' OR i.aliases CONTAINS 'electrical'
}
RETURN count(DISTINCT c) AS numberOfCompanies"
  ,
  "rationale": "This query counts distinct companies that either have a CEO named 'Bob Swan' or operate in an industry matching 'electrical industry'. Both conditions are checked via EXISTS subqueries to handle the OR relationship properly, and the count is distinct to avoid double-counting companies that match both criteria." 
}

